}

managed implementation in class ZBP_R_ZTRAVEL unique;
strict ( 2 );
with draft;
extensible;
define behavior for ZR_ZTRAVEL alias ZrSflight
persistent table ZTRAVEL
extensible
draft table ZZTRAVEL_D
lock master
authorization master( global )
{
  field ( mandatory : create )
   Carrid,
   Connid,
   Fldate;

  field ( readonly : update )
   Carrid,
   Connid,
   Fldate;


  create;
  update;
  delete;

  draft action Activate optimized;
  draft action Discard;
  draft action Edit;
  draft action Resume;
  draft determine action Prepare;

  mapping for ZTRAVEL corresponding extensible
  {
    Carrid = carrid;
    Connid = connid;
    Fldate = fldate;
    Price = price;
    Currency = currency;
    Planetype = planetype;
    Seatsmax = seatsmax;
    Seatsocc = seatsocc;
    Paymentsum = paymentsum;
    SeatsmaxB = seatsmax_b;
    SeatsoccB = seatsocc_b;
    SeatsmaxF = seatsmax_f;
    SeatsoccF = seatsocc_f;
  }

}

