@EndUserText.label : 'Draft Database Table for ZZTRAVEL_D'
@AbapCatalog.enhancement.category : #EXTENSIBLE_ANY
@AbapCatalog.tableCategory : #TRANSPARENT
@AbapCatalog.deliveryClass : #A
@AbapCatalog.dataMaintenance : #RESTRICTED
define table zztravel_d {

  key mandt  : mandt not null;
  key carrid : s_carr_id not null;
  key connid : s_conn_id not null;
  key fldate : s_date not null;
  @Semantics.amount.currencyCode : 'zztravel_d.currency'
  price      : s_price;
  currency   : s_currcode;
  planetype  : s_planetye;
  seatsmax   : s_seatsmax;
  seatsocc   : s_seatsocc;
  @Semantics.amount.currencyCode : 'zztravel_d.currency'
  paymentsum : s_sum;
  seatsmaxb  : s_smax_b;
  seatsoccb  : s_socc_b;
  seatsmaxf  : s_smax_f;
  seatsoccf  : s_socc_f;
  "%admin"   : include sych_bdl_draft_admin_inc;
}
